195	
196	/** The opening balances box: lines of name,period,amount, each adding the amount to the named
197	 *  person's carried figure for the period (their opening balance for it). */
198	@Service
199	public class OpeningImportService {
200	
201	    /** An opening amount: 0.00 or more, with exactly two decimals. */
202	    private static final Pattern AMOUNT = Pattern.compile("\\s*\\d{1,12}\\.\\d{2}\\s*");
203	
204	    /** One parsed line: the person, the period and the amount. */
205	    private record Line(Person person, Period period, BigDecimal amount) {
206	    }
207	
208	    private final PersonRepository people;
209	    private final PeriodRepository periods;
210	    private final SheetService sheets;
211	    private final History history;
212	    private final Audit audit;
213	
214	    public OpeningImportService(PersonRepository people, PeriodRepository periods, SheetService sheets,
215	            History history, Audit audit) {
216	        this.people = people;
217	        this.periods = periods;
218	        this.sheets = sheets;
219	        this.history = history;
220	        this.audit = audit;
221	    }
222	
223	    /** What an import came to: how many lines went through, and the periods they changed. */
224	    public record Imported(int added, List<Period> periods) {
225	    }
226	
227	    /** Add each line's amount to its person's opening balance for its period, in order, checking
228	     *  every line first; one change, so when any line is refused nothing is changed and nothing is
229	     *  recorded. A person is named by name or alias and a period by name, without regard to case.
230	     *  Blank lines are skipped; an import with no lines is refused. */
231	    @Transactional
232	    public Imported importOpenings(String sheetId, String user, String text) {
233	        sheets.load(sheetId, user);
234	        List<Period> onSheet = periods.findBySheetIdOrderByFromDateAsc(sheetId);
235	        List<Line> lines = new ArrayList<>();
236	        int n = 0;
237	        for (String raw : text.split("\\R")) {
238	            n++;
239	            if (!raw.isBlank()) {
240	                lines.add(parse(sheetId, onSheet, n, raw));
241	            }
242	        }
243	        if (lines.isEmpty()) {
244	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
245	        }
246	        Map<Long, Period> changed = new LinkedHashMap<>();
247	        for (Line line : lines) {
248	            Period period = changed.computeIfAbsent(line.period().getId(), id -> periods.lockByIdAndSheetId(id, sheetId)
249	                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet")));
250	            period.addOpening(line.person().getId(), line.amount());
251	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + line.person().getName()
252	                    + " period=" + period.getName() + " amount=" + line.amount().toPlainString());
253	        }
254	        List<Period> saved = periods.saveAllAndFlush(changed.values());
255	        history.record(sheetId);
256	        return new Imported(lines.size(), saved);
257	    }
258	
259	    /** A line of name,period,amount. */
260	    private Line parse(String sheetId, List<Period> onSheet, int n, String raw) {
261	        String[] fields = raw.split(",", -1);
262	        if (fields.length != 3) {
263	            throw refused(n, "expected name,period,amount");
264	        }
265	        String name = fields[0].trim();
266	        Person person = name.isEmpty() ? null : people.findByNameOrAlias(sheetId, name).orElse(null);
267	        if (person == null) {
268	            throw refused(n, "no one named \"" + name + "\" on this sheet");
269	        }
270	        String periodName = fields[1].trim();
271	        Period period = onSheet.stream().filter(p -> p.getName().equalsIgnoreCase(periodName)).findFirst()
272	                .orElseThrow(() -> refused(n, "no period named \"" + periodName + "\" on this sheet"));
273	        if (!AMOUNT.matcher(fields[2]).matches()) {
274	            throw refused(n, "the amount must be 0.00 or more, with two decimals");
275	        }
276	        return new Line(person, period, new BigDecimal(fields[2].trim()));
277	    }
278	
279	    private static ResponseStatusException refused(int n, String why) {
280	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": " + why);
281	    }
282	}
