312	/** The periods on a sheet: named, each running from a day to a day, none overlapping another. */
313	@Service
314	public class PeriodService {
315	
316	    private final PeriodRepository periods;
317	    private final SheetService sheets;
318	    private final ClaimRepository claims;
319	    private final PersonRepository people;
320	    private final Dues dues;
321	    private final RoleService roles;
