325	    public PeriodService(PeriodRepository periods, SheetService sheets, ClaimRepository claims,
326	            PersonRepository people, Dues dues, RoleService roles, History history, Audit audit) {
327	        this.history = history;
328	        this.periods = periods;
329	        this.sheets = sheets;
330	        this.claims = claims;
331	        this.people = people;
332	        this.dues = dues;
