336	
337	    /** The periods on the sheet, earliest first. */
338	    @Transactional(readOnly = true)
339	    public List<Period> list(String sheetId) {
340	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
341	    }
342	
343	    /** Add a period, capping each person's open or pending claims in it when a cap is given (null:
344	     *  none); refused when its to-date is before its from-date, its cap is below 1, its name is in use
345	     *  on the sheet, or it shares a day with another period. */
346	    @Transactional
347	    public synchronized Period add(String sheetId, String user, String name, LocalDate from, LocalDate to,
348	            Integer cap) {
349	        sheets.load(sheetId, user);
350	        if (cap != null && cap < 1) {
351	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's claim cap must be at least 1");
352	        }
353	        if (to.isBefore(from)) {
354	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts");
355	        }
356	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
357	            throw nameInUse();
358	        }
359	        if (periods.overlaps(sheetId, from, to)) {
360	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another on this sheet");
361	        }
362	        Period saved;
363	        try {
364	            saved = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
365	        } catch (DataIntegrityViolationException e) {
366	            throw nameInUse();
367	        }
368	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
369	                + " from=" + saved.getFromDate() + " to=" + saved.getToDate()
370	                + (saved.getClaimCap() == null ? "" : " cap=" + saved.getClaimCap()));
371	        history.record(sheetId);
372	        return saved;
373	    }
374	
375	    /** Generate one period per calendar month from the from-date's month to the to-date's month
376	     *  (the from-date the sheet's today when none is given), each running from the first to the last
377	     *  day of its month and named yyyy-mm; a month whose name is in use on the sheet, or whose days
378	     *  overlap a period on it, is left out. Refused when the to-date is before the from-date. */
379	    @Transactional
380	    public synchronized List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
381	        sheets.load(sheetId, user);
382	        if (from == null) {
383	            from = sheets.today(sheetId);
384	        }
385	        if (to.isBefore(from)) {
386	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date");
387	        }
388	        List<Period> made = new ArrayList<>();
389	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
390	            String name = month.toString();
391	            LocalDate first = month.atDay(1);
392	            LocalDate last = month.atEndOfMonth();
393	            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name) || periods.overlaps(sheetId, first, last)) {
394	                continue;
395	            }
396	            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
397	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
398	                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
399	            made.add(saved);
400	        }
401	        history.record(sheetId);
402	        return made;
403	    }
404	
405	    /** Generate the twelve monthly periods of the fiscal year named by the year, as {@link #generate}
406	     *  does, from the first day of the sheet's fiscal year start month in that year. */
407	    @Transactional
408	    public synchronized List<Period> generateFiscalYear(String sheetId, String user, int year) {
409	        LocalDate first = LocalDate.of(year, sheets.fiscalStartMonth(sheetId), 1);
410	        return generate(sheetId, user, first, first.plusMonths(12).minusDays(1));
411	    }
412	
413	    /** Generate the four calendar quarters of the year, each running from the first day of its
414	     *  first month to the last day of its third month and named yyyy-Qn; a quarter whose name is in
415	     *  use on the sheet, or whose days overlap a period on it, is left out. */
416	    @Transactional
417	    public synchronized List<Period> generateQuarters(String sheetId, String user, int year) {
418	        sheets.load(sheetId, user);
419	        List<Period> made = new ArrayList<>();
420	        for (int quarter = 1; quarter <= 4; quarter++) {
421	            String name = year + "-Q" + quarter;
422	            LocalDate first = LocalDate.of(year, quarter * 3 - 2, 1);
423	            LocalDate last = YearMonth.of(year, quarter * 3).atEndOfMonth();
424	            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name) || periods.overlaps(sheetId, first, last)) {
425	                continue;
426	            }
427	            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
428	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
429	                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
430	            made.add(saved);
431	        }
432	        history.record(sheetId);
433	        return made;
434	    }
435	
436	    /** The fiscal year a day falls in (FYyyyy), with fiscal years starting on the first day of the
437	     *  month: named by the calendar year that first day falls in. */
438	    public static String fiscalYear(LocalDate day, int fiscalStartMonth) {
439	        return "FY" + (day.getMonthValue() >= fiscalStartMonth ? day.getYear() : day.getYear() - 1);
440	    }
