442	    /** Close a period (an open or a soft-closed one), fixing its due-total at what it is now; refused when the permission matrix does
443	     *  not allow the user's role to close, or it is already closed. */
444	    @Transactional
445	    public Period close(String sheetId, String user, long periodId) {
446	        sheets.load(sheetId, user);
447	        if (!roles.may(sheetId, user, "close")) {
448	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
449	        }
450	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
451	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
452	        if (period.isClosed()) {
453	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
454	        }
455	        return closeOpen(sheetId, user, period, "");
456	    }
457	
458	    /** Soft-close a period, fixing its due-total and each person's for it at what they are now while
459	     *  claims dated inside it stay open to change; refused when the permission matrix does not allow
460	     *  the user's role to close, or it is already closed or soft-closed. */
461	    @Transactional
462	    public Period softClose(String sheetId, String user, long periodId) {
463	        sheets.load(sheetId, user);
464	        if (!roles.may(sheetId, user, "close")) {
465	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
466	        }
467	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
468	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
469	        if (period.isClosed() || period.isSoftClosed()) {
470	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
471	        }
472	        period.softClose(personTotals(sheetId, period), personCarried(sheetId, period));
473	        Period saved = periods.saveAndFlush(period);
474	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
475	                + " total=" + saved.getClosedTotal().toPlainString());
476	        history.record(sheetId);
477	        return saved;
478	    }
