480	    /** Close every open period on the sheet whose to-date plus the grace days is before the day,
481	     *  earliest to-date first, each as a close by hand would, its record marked auto=yes. */
482	    @Transactional(propagation = Propagation.MANDATORY)
483	    public void autoClose(String sheetId, String user, int graceDays, LocalDate day) {
484	        for (Period period : periods.findOpenEndingBefore(sheetId, day.minusDays(graceDays))) {
485	            closeOpen(sheetId, user, period, " auto=yes");
486	        }
487	    }
