489	    /** Close an open period, fixing its due-total at what it is now; the suffix ends its record. */
490	    private Period closeOpen(String sheetId, String user, Period period, String suffix) {
491	        period.close(personTotals(sheetId, period), personCarried(sheetId, period));
492	        Period saved = periods.saveAndFlush(period);
493	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
494	                + " total=" + saved.getClosedTotal().toPlainString() + suffix);
495	        history.record(sheetId);
496	        return saved;
497	    }
