499	    /** Reopen a closed or soft-closed period, making its due-total live again; refused when the permission matrix
500	     *  does not allow the user's role to reopen, the period is not closed, or it is locked. */
501	    @Transactional
502	    public Period reopen(String sheetId, String user, long periodId) {
503	        sheets.load(sheetId, user);
504	        if (!roles.may(sheetId, user, "reopen")) {
505	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
506	        }
507	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
508	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
509	        if (!period.isClosed() && !period.isSoftClosed()) {
510	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
511	        }
512	        if (period.isLocked()) {
513	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is locked");
514	        }
515	        period.reopen();
516	        Period saved = periods.saveAndFlush(period);
517	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
518	        history.record(sheetId);
519	        return saved;
520	    }
