522	    /** Lock or unlock a period; refused unless the user acts as a steward, or when it is already
523	     *  locked (or, to unlock, not locked). */
524	    @Transactional
525	    public Period lock(String sheetId, String user, long periodId, boolean lock) {
526	        sheets.load(sheetId, user);
527	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
528	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
529	                    "Only a steward may " + (lock ? "lock" : "unlock") + " a period");
530	        }
531	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
532	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
533	        if (period.isLocked() == lock) {
534	            throw new ResponseStatusException(HttpStatus.CONFLICT,
535	                    lock ? "That period is already locked" : "That period is not locked");
536	        }
537	        period.setLocked(lock);
538	        Period saved = periods.saveAndFlush(period);
539	        audit.recordOnCommit((lock ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user
540	                + " period=" + saved.getName());
541	        history.record(sheetId);
542	        return saved;
543	    }
544	
545	    /** Each person's due-total for a period, by the person's id: the due figures of their claims
546	     *  whose due-by falls in it and that count by their status at its end, skipping those with no due
547	     *  and those the live rules leave out (see Dues#countsAsOf). */
548	    private Map<Long, BigDecimal> personTotals(String sheetId, Period period) {
549	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
550	                .collect(Collectors.toMap(Person::getId, Function.identity()));
551	        Map<Long, BigDecimal> totals = new HashMap<>();
552	        for (Long id : byId.keySet()) {
553	            totals.put(id, BigDecimal.ZERO.setScale(2));
554	        }
555	        LocalDate today = sheets.today(sheetId);
556	        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
557	            Person person = byId.get(c.getPersonId());
558	            if (person == null || !Dues.countsAsOf(person, c, period.getToDate(), today) || c.getDueBy().isBefore(period.getFromDate())
559	                    || c.getDueBy().isAfter(period.getToDate())) {
560	                continue;
561	            }
562	            BigDecimal figure = dues.figure(sheetId, person, c);
563	            if (figure != null) {
564	                totals.merge(person.getId(), figure, BigDecimal::add);
565	            }
566	        }
567	        return totals;
568	    }
569	
570	    /** Each person's carried figure for a period, by the person's id: their opening balance for it
571	     *  plus the due figures of their claims that count by their status at its end whose due-by falls
572	     *  in a period ending before it starts and that were still open (or pending) at its end, skipping
573	     *  those with no due. */
574	    private Map<Long, BigDecimal> personCarried(String sheetId, Period period) {
575	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
576	                .collect(Collectors.toMap(Person::getId, Function.identity()));
577	        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
578	        Map<Long, BigDecimal> carried = new HashMap<>();
579	        for (Long id : byId.keySet()) {
580	            carried.put(id, period.getPersonOpenings().getOrDefault(id, BigDecimal.ZERO).setScale(2));
581	        }
582	        LocalDate today = sheets.today(sheetId);
583	        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
584	            Person person = byId.get(c.getPersonId());
585	            boolean earlier = all.stream().anyMatch(p -> !c.getDueBy().isBefore(p.getFromDate())
586	                    && !c.getDueBy().isAfter(p.getToDate()) && p.getToDate().isBefore(period.getFromDate()));
587	            if (person == null || !earlier || !Dues.countsAsOf(person, c, period.getToDate(), today)) {
588	                continue;
589	            }
590	            ClaimStatus then = c.statusOn(period.getToDate());
591	            if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
592	                continue;
593	            }
594	            BigDecimal figure = dues.figure(sheetId, person, c);
595	            if (figure != null) {
596	                carried.merge(person.getId(), figure, BigDecimal::add);
597	            }
598	        }
599	        return carried;
600	    }
601	
602	    private static ResponseStatusException nameInUse() {
603	        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
604	    }
605	}
