package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.AsOfGuard;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/periods")
@Validated
public class PeriodController {

    /** What the screen shows of a period: its name, the days it runs from and to, inclusive, whether
     *  it is closed or soft-closed, the due-total fixed when it was closed (null while it is open), and each
     *  person's due-total for it fixed then, by the person's id (empty while it is open), and the
     *  fiscal year its from-date falls in (FYyyyy), and the most open or pending claims a person may
     *  have in it (null: no cap), and each person's carried figure for it fixed when it was closed, by
     *  the person's id (empty while it is open), and each person's opening balance for it, by the
     *  person's id (a person missing has 0.00), and whether a steward has locked it. */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, boolean closed,
            boolean softClosed, String closedTotal, Map<Long, String> closedPersonTotals, String fy, Integer cap,
            Map<Long, String> closedPersonCarried, Map<Long, String> personOpenings, boolean locked) {
        static PeriodView of(Period period, int fiscalStartMonth) {
            Map<Long, String> personTotals = new TreeMap<>();
            period.getPersonTotals().forEach((id, total) -> personTotals.put(id, total.setScale(2).toPlainString()));
            Map<Long, String> personCarried = new TreeMap<>();
            period.getPersonCarried().forEach((id, carried) -> personCarried.put(id, carried.setScale(2).toPlainString()));
            Map<Long, String> personOpenings = new TreeMap<>();
            period.getPersonOpenings().forEach((id, opening) -> personOpenings.put(id, opening.setScale(2).toPlainString()));
            return new PeriodView(period.getId(), period.getName(), period.getFromDate(), period.getToDate(),
                    period.isClosed(), period.isSoftClosed(),
                    period.getClosedTotal() == null ? null : period.getClosedTotal().setScale(2).toPlainString(),
                    personTotals, PeriodService.fiscalYear(period.getFromDate(), fiscalStartMonth),
                    period.getClaimCap(), personCarried, personOpenings, period.isLocked());
        }
    }

    /** The period form: a required name, the required days it runs from and to, and the most open
     *  or pending claims a person may have in it (a whole number of 1 or more; null for no cap). */
    public record PeriodForm(@NotBlank @Size(max = 100) String name, @NotNull LocalDate from,
            @NotNull LocalDate to, @Min(1) Integer cap) {
    }

    /** The generate form: the day whose month the periods start from (the sheet's today when none
     *  is given), and the required day whose month they end with. */
    public record GenerateForm(LocalDate from, @NotNull LocalDate to) {
    }

    /** The generate fiscal year (or quarters) form: the required year (yyyy) the fiscal year is
     *  named by, or whose calendar quarters are generated. */
    public record GenerateFyForm(@NotBlank @Pattern(regexp = "\\s*\\d{4}\\s*") String year) {

        int yearValue() {
            return Integer.parseInt(year.trim());
        }
    }

    private final PeriodService service;
    private final SheetService sheets;
    private final History history;

    public PeriodController(PeriodService service, SheetService sheets, History history) {
        this.service = service;
        this.sheets = sheets;
        this.history = history;
    }

    /** The view of a period on the sheet. */
    private PeriodView view(String sheetId, Period period) {
        return PeriodView.of(period, sheets.fiscalStartMonth(sheetId));
    }

    /** The periods on the sheet, earliest first; as of a day when one is given, as they stood at the
     *  end of it (see {@link History}). */
    @GetMapping
    public List<PeriodView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        List<Period> periods = asOf != null ? history.asOf(sheetId.trim(), asOf).periods()
                : service.list(sheetId.trim());
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return periods.stream().map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PeriodForm form) {
        return view(sheetId.trim(), service.add(sheetId.trim(), user.trim(), form.name().trim(), form.from(), form.to(), form.cap()));
    }

    @PostMapping("/generate")
    public List<PeriodView> generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateForm form) {
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return service.generate(sheetId.trim(), user.trim(), form.from(), form.to()).stream()
                .map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping("/generate-fy")
    public List<PeriodView> generateFy(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateFyForm form) {
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return service.generateFiscalYear(sheetId.trim(), user.trim(), form.yearValue()).stream()
                .map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping("/generate-quarters")
    public List<PeriodView> generateQuarters(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateFyForm form) {
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return service.generateQuarters(sheetId.trim(), user.trim(), form.yearValue()).stream()
                .map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping("/{periodId}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.close(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/soft-close")
    public PeriodView softClose(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.softClose(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/reopen")
    public PeriodView reopen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.reopen(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/lock")
    public PeriodView lock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.lock(sheetId.trim(), user.trim(), periodId, true));
    }

    @PostMapping("/{periodId}/unlock")
    public PeriodView unlock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.lock(sheetId.trim(), user.trim(), periodId, false));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The opening balances box: lines of name,period,amount, each adding the amount to the named
 *  person's carried figure for the period (their opening balance for it). */
@Service
public class OpeningImportService {

    /** An opening amount: 0.00 or more, with exactly two decimals. */
    private static final Pattern AMOUNT = Pattern.compile("\\s*\\d{1,12}\\.\\d{2}\\s*");

    /** One parsed line: the person, the period and the amount. */
    private record Line(Person person, Period period, BigDecimal amount) {
    }

    private final PersonRepository people;
    private final PeriodRepository periods;
    private final SheetService sheets;
    private final History history;
    private final Audit audit;

    public OpeningImportService(PersonRepository people, PeriodRepository periods, SheetService sheets,
            History history, Audit audit) {
        this.people = people;
        this.periods = periods;
        this.sheets = sheets;
        this.history = history;
        this.audit = audit;
    }

    /** What an import came to: how many lines went through, and the periods they changed. */
    public record Imported(int added, List<Period> periods) {
    }

    /** Add each line's amount to its person's opening balance for its period, in order, checking
     *  every line first; one change, so when any line is refused nothing is changed and nothing is
     *  recorded. A person is named by name or alias and a period by name, without regard to case.
     *  Blank lines are skipped; an import with no lines is refused. */
    @Transactional
    public Imported importOpenings(String sheetId, String user, String text) {
        sheets.load(sheetId, user);
        List<Period> onSheet = periods.findBySheetIdOrderByFromDateAsc(sheetId);
        List<Line> lines = new ArrayList<>();
        int n = 0;
        for (String raw : text.split("\\R")) {
            n++;
            if (!raw.isBlank()) {
                lines.add(parse(sheetId, onSheet, n, raw));
            }
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
        }
        Map<Long, Period> changed = new LinkedHashMap<>();
        for (Line line : lines) {
            Period period = changed.computeIfAbsent(line.period().getId(), id -> periods.lockByIdAndSheetId(id, sheetId)
                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet")));
            period.addOpening(line.person().getId(), line.amount());
            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + line.person().getName()
                    + " period=" + period.getName() + " amount=" + line.amount().toPlainString());
        }
        List<Period> saved = periods.saveAllAndFlush(changed.values());
        history.record(sheetId);
        return new Imported(lines.size(), saved);
    }

    /** A line of name,period,amount. */
    private Line parse(String sheetId, List<Period> onSheet, int n, String raw) {
        String[] fields = raw.split(",", -1);
        if (fields.length != 3) {
            throw refused(n, "expected name,period,amount");
        }
        String name = fields[0].trim();
        Person person = name.isEmpty() ? null : people.findByNameOrAlias(sheetId, name).orElse(null);
        if (person == null) {
            throw refused(n, "no one named \"" + name + "\" on this sheet");
        }
        String periodName = fields[1].trim();
        Period period = onSheet.stream().filter(p -> p.getName().equalsIgnoreCase(periodName)).findFirst()
                .orElseThrow(() -> refused(n, "no period named \"" + periodName + "\" on this sheet"));
        if (!AMOUNT.matcher(fields[2]).matches()) {
            throw refused(n, "the amount must be 0.00 or more, with two decimals");
        }
        return new Line(person, period, new BigDecimal(fields[2].trim()));
    }

    private static ResponseStatusException refused(int n, String why) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": " + why);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The periods on a sheet: named, each running from a day to a day, none overlapping another. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final Dues dues;
    private final RoleService roles;
    private final History history;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetService sheets, ClaimRepository claims,
            PersonRepository people, Dues dues, RoleService roles, History history, Audit audit) {
        this.history = history;
        this.periods = periods;
        this.sheets = sheets;
        this.claims = claims;
        this.people = people;
        this.dues = dues;
        this.roles = roles;
        this.audit = audit;
    }

    /** The periods on the sheet, earliest first. */
    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    /** Add a period, capping each person's open or pending claims in it when a cap is given (null:
     *  none); refused when its to-date is before its from-date, its cap is below 1, its name is in use
     *  on the sheet, or it shares a day with another period. */
    @Transactional
    public synchronized Period add(String sheetId, String user, String name, LocalDate from, LocalDate to,
            Integer cap) {
        sheets.load(sheetId, user);
        if (cap != null && cap < 1) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's claim cap must be at least 1");
        }
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts");
        }
        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
            throw nameInUse();
        }
        if (periods.overlaps(sheetId, from, to)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another on this sheet");
        }
        Period saved;
        try {
            saved = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " from=" + saved.getFromDate() + " to=" + saved.getToDate()
                + (saved.getClaimCap() == null ? "" : " cap=" + saved.getClaimCap()));
        history.record(sheetId);
        return saved;
    }

    /** Generate one period per calendar month from the from-date's month to the to-date's month
     *  (the from-date the sheet's today when none is given), each running from the first to the last
     *  day of its month and named yyyy-mm; a month whose name is in use on the sheet, or whose days
     *  overlap a period on it, is left out. Refused when the to-date is before the from-date. */
    @Transactional
    public synchronized List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        sheets.load(sheetId, user);
        if (from == null) {
            from = sheets.today(sheetId);
        }
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date");
        }
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name) || periods.overlaps(sheetId, first, last)) {
                continue;
            }
            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
            made.add(saved);
        }
        history.record(sheetId);
        return made;
    }

    /** Generate the twelve monthly periods of the fiscal year named by the year, as {@link #generate}
     *  does, from the first day of the sheet's fiscal year start month in that year. */
    @Transactional
    public synchronized List<Period> generateFiscalYear(String sheetId, String user, int year) {
        LocalDate first = LocalDate.of(year, sheets.fiscalStartMonth(sheetId), 1);
        return generate(sheetId, user, first, first.plusMonths(12).minusDays(1));
    }

    /** Generate the four calendar quarters of the year, each running from the first day of its
     *  first month to the last day of its third month and named yyyy-Qn; a quarter whose name is in
     *  use on the sheet, or whose days overlap a period on it, is left out. */
    @Transactional
    public synchronized List<Period> generateQuarters(String sheetId, String user, int year) {
        sheets.load(sheetId, user);
        List<Period> made = new ArrayList<>();
        for (int quarter = 1; quarter <= 4; quarter++) {
            String name = year + "-Q" + quarter;
            LocalDate first = LocalDate.of(year, quarter * 3 - 2, 1);
            LocalDate last = YearMonth.of(year, quarter * 3).atEndOfMonth();
            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name) || periods.overlaps(sheetId, first, last)) {
                continue;
            }
            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
            made.add(saved);
        }
        history.record(sheetId);
        return made;
    }

    /** The fiscal year a day falls in (FYyyyy), with fiscal years starting on the first day of the
     *  month: named by the calendar year that first day falls in. */
    public static String fiscalYear(LocalDate day, int fiscalStartMonth) {
        return "FY" + (day.getMonthValue() >= fiscalStartMonth ? day.getYear() : day.getYear() - 1);
    }

    /** Close a period (an open or a soft-closed one), fixing its due-total at what it is now; refused when the permission matrix does
     *  not allow the user's role to close, or it is already closed. */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        sheets.load(sheetId, user);
        if (!roles.may(sheetId, user, "close")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
        }
        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
        }
        return closeOpen(sheetId, user, period, "");
    }

    /** Soft-close a period, fixing its due-total and each person's for it at what they are now while
     *  claims dated inside it stay open to change; refused when the permission matrix does not allow
     *  the user's role to close, or it is already closed or soft-closed. */
    @Transactional
    public Period softClose(String sheetId, String user, long periodId) {
        sheets.load(sheetId, user);
        if (!roles.may(sheetId, user, "close")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
        }
        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isClosed() || period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
        }
        period.softClose(personTotals(sheetId, period), personCarried(sheetId, period));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString());
        history.record(sheetId);
        return saved;
    }

    /** Close every open period on the sheet whose to-date plus the grace days is before the day,
     *  earliest to-date first, each as a close by hand would, its record marked auto=yes. */
    @Transactional(propagation = Propagation.MANDATORY)
    public void autoClose(String sheetId, String user, int graceDays, LocalDate day) {
        for (Period period : periods.findOpenEndingBefore(sheetId, day.minusDays(graceDays))) {
            closeOpen(sheetId, user, period, " auto=yes");
        }
    }

    /** Close an open period, fixing its due-total at what it is now; the suffix ends its record. */
    private Period closeOpen(String sheetId, String user, Period period, String suffix) {
        period.close(personTotals(sheetId, period), personCarried(sheetId, period));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString() + suffix);
        history.record(sheetId);
        return saved;
    }

    /** Reopen a closed or soft-closed period, making its due-total live again; refused when the permission matrix
     *  does not allow the user's role to reopen, the period is not closed, or it is locked. */
    @Transactional
    public Period reopen(String sheetId, String user, long periodId) {
        sheets.load(sheetId, user);
        if (!roles.may(sheetId, user, "reopen")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
        }
        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
        }
        if (period.isLocked()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is locked");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        history.record(sheetId);
        return saved;
    }

    /** Lock or unlock a period; refused unless the user acts as a steward, or when it is already
     *  locked (or, to unlock, not locked). */
    @Transactional
    public Period lock(String sheetId, String user, long periodId, boolean lock) {
        sheets.load(sheetId, user);
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "Only a steward may " + (lock ? "lock" : "unlock") + " a period");
        }
        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
        if (period.isLocked() == lock) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    lock ? "That period is already locked" : "That period is not locked");
        }
        period.setLocked(lock);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit((lock ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user
                + " period=" + saved.getName());
        history.record(sheetId);
        return saved;
    }

    /** Each person's due-total for a period, by the person's id: the due figures of their claims
     *  whose due-by falls in it and that count by their status at its end, skipping those with no due
     *  and those the live rules leave out (see Dues#countsAsOf). */
    private Map<Long, BigDecimal> personTotals(String sheetId, Period period) {
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, BigDecimal> totals = new HashMap<>();
        for (Long id : byId.keySet()) {
            totals.put(id, BigDecimal.ZERO.setScale(2));
        }
        LocalDate today = sheets.today(sheetId);
        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            Person person = byId.get(c.getPersonId());
            if (person == null || !Dues.countsAsOf(person, c, period.getToDate(), today) || c.getDueBy().isBefore(period.getFromDate())
                    || c.getDueBy().isAfter(period.getToDate())) {
                continue;
            }
            BigDecimal figure = dues.figure(sheetId, person, c);
            if (figure != null) {
                totals.merge(person.getId(), figure, BigDecimal::add);
            }
        }
        return totals;
    }

    /** Each person's carried figure for a period, by the person's id: their opening balance for it
     *  plus the due figures of their claims that count by their status at its end whose due-by falls
     *  in a period ending before it starts and that were still open (or pending) at its end, skipping
     *  those with no due. */
    private Map<Long, BigDecimal> personCarried(String sheetId, Period period) {
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
        Map<Long, BigDecimal> carried = new HashMap<>();
        for (Long id : byId.keySet()) {
            carried.put(id, period.getPersonOpenings().getOrDefault(id, BigDecimal.ZERO).setScale(2));
        }
        LocalDate today = sheets.today(sheetId);
        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            Person person = byId.get(c.getPersonId());
            boolean earlier = all.stream().anyMatch(p -> !c.getDueBy().isBefore(p.getFromDate())
                    && !c.getDueBy().isAfter(p.getToDate()) && p.getToDate().isBefore(period.getFromDate()));
            if (person == null || !earlier || !Dues.countsAsOf(person, c, period.getToDate(), today)) {
                continue;
            }
            ClaimStatus then = c.statusOn(period.getToDate());
            if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
                continue;
            }
            BigDecimal figure = dues.figure(sheetId, person, c);
            if (figure != null) {
                carried.merge(person.getId(), figure, BigDecimal::add);
            }
        }
        return carried;
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
    }
}

