protected readonly calendar = computed(() => {
  const by = new Map<string, string>();
  for (const g of this.grades) {
    for (const m of this.months()) {
      const pct = pctOn(this.rates(), g, `${m}-01`);
      if (pct !== undefined) by.set(`${g}-${m}`, pct);
    }
  }
  return by;
});

